"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { useControllableState } from "../lib/hooks";

export interface SwitchProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange" | "value"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  label?: React.ReactNode;
  description?: React.ReactNode;
  size?: "sm" | "md";
  /** Label links van de schakelaar in plaats van rechts. */
  labelPosition?: "left" | "right";
}

/** Switch — aan/uit-schakelaar (role="switch"). */
export const Switch = React.forwardRef<HTMLButtonElement, SwitchProps>(function Switch(
  {
    checked,
    defaultChecked = false,
    onCheckedChange,
    label,
    description,
    size = "md",
    labelPosition = "right",
    className,
    disabled,
    onClick,
    ...rest
  },
  ref
) {
  const [on, setOn] = useControllableState<boolean>({
    value: checked,
    defaultValue: defaultChecked,
    onChange: onCheckedChange,
  });

  const control = (
    // onClick staat bewust ná {...rest}: anders overschrijft een eigen onClick
    // de handler die de schakelaar omzet, en schakelt hij niet meer.
    <button
      ref={ref}
      type="button"
      role="switch"
      aria-checked={on}
      disabled={disabled}
      data-state={on ? "on" : "off"}
      className={cn("lui-switch", `lui-switch-${size}`, !label && !description && className)}
      {...rest}
      onClick={(event) => {
        onClick?.(event);
        setOn(!on);
      }}
    >
      <span className="lui-switch-thumb" />
    </button>
  );

  if (!label && !description) return control;

  return (
    <label className={cn("lui-switch-row", labelPosition === "left" && "lui-switch-row-reverse", disabled && "lui-switch-row-disabled", className)}>
      {control}
      <span className="lui-switch-text">
        {label && <span className="lui-switch-label">{label}</span>}
        {description && <span className="lui-switch-description">{description}</span>}
      </span>
    </label>
  );
});

/* ============================ Switch ============================ */
.lui-switch {
  position: relative; width: 40px; height: 23px; flex: none; padding: 0;
  border: none; border-radius: var(--r-full); background: var(--border-strong);
  cursor: pointer; transition: background var(--dur);
}
.lui-switch:focus-visible { outline: none; box-shadow: var(--ring); }
.lui-switch:disabled { opacity: .5; cursor: not-allowed; }
.lui-switch-thumb {
  position: absolute; top: 2.5px; left: 2.5px;
  width: 18px; height: 18px; border-radius: var(--r-full);
  background: var(--surface); box-shadow: var(--sh-sm);
  transition: transform var(--dur) var(--ease);
}
.lui-switch[data-state="on"] { background: var(--accent); }
.lui-switch[data-state="on"] .lui-switch-thumb { transform: translateX(17px); }

.lui-switch-sm { width: 32px; height: 19px; }
.lui-switch-sm .lui-switch-thumb { width: 14px; height: 14px; top: 2.5px; left: 2.5px; }
.lui-switch-sm[data-state="on"] .lui-switch-thumb { transform: translateX(13px); }

.lui-switch-row { display: flex; align-items: flex-start; gap: 11px; cursor: pointer; }
.lui-switch-row-reverse { flex-direction: row-reverse; justify-content: space-between; }
.lui-switch-row-disabled { cursor: not-allowed; opacity: .6; }
.lui-switch-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.lui-switch-label { font-size: 13.5px; font-weight: 550; color: var(--text); line-height: 1.35; }
.lui-switch-description { font-size: var(--fs-sm); color: var(--text-3); line-height: 1.45; }

/* ---------- Motion: verende duim die uitrekt terwijl je drukt ---------- */
.lui-switch-thumb { transition: transform .32s var(--ease-pop), width .2s var(--ease-out); }
.lui-switch:active:not(:disabled) .lui-switch-thumb { width: 23px; }
.lui-switch[data-state="on"]:active:not(:disabled) .lui-switch-thumb { transform: translateX(12px); }
.lui-switch-sm:active:not(:disabled) .lui-switch-thumb { width: 18px; }
.lui-switch-sm[data-state="on"]:active:not(:disabled) .lui-switch-thumb { transform: translateX(9px); }
